    if plat_mod.system() != "Windows":
        return cmd

    script = cmd[0]
    # Attempt to read the shebang line if the first element is a file
    try:
        with open(script, "rb") as f:
            first_line = f.readline().decode("utf-8", errors="ignore")
    except Exception:
        return cmd

    if not first_line.startswith("#!"):
        return cmd

    # Parse the shebang line to determine the interpreter
    interpreter_line = first_line[2:].strip()
    parts = interpreter_line.split()
    if not parts:
        return cmd

    # Handle a shebang that uses env, e.g. "#!/usr/bin/env python"
    if parts[0].lower() == "env":
        # Use the current python interpreter
        interpreter = sys_mod.executable
    else:
        interpreter = parts[0]

    # If the interpreter looks like a python executable, use the current interpreter
    if interpreter.lower().endswith("python"):
        interpreter = sys_mod.executable

    # Build the new command tuple
    new_cmd = (interpreter,) + cmd[1:]
    return new_cmd

