def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # The function constructs a default observer schema for every resource in the
    # application manifest that does not already declare a custom observer
    # configuration.  The default schema simply observes the status of the
    # resource and expects a `Ready` condition to become `True`.
    if not hasattr(app, "spec"):
        return {}

    manifest = getattr(app.spec, "manifest", [])
    defaults = {}

    for resource in manifest:
        if not isinstance(resource, dict):
            continue

        # Skip if the resource explicitly defines an observer schema.
        if resource.get("spec", {}).get("observer"):
            continue

        kind = resource.get("kind")
        metadata = resource.get("metadata", {})
        name = metadata.get("name")

        if not kind or not name:
            continue

        key = f"{kind}/{name}"
        defaults[key] = {
            "kind": kind,
            "metadata": {"name": name},
            "status": {
                "conditions": [
                    {"type": "Ready", "status": "True"}
                ]
            },
        }

    # Store the generated default schemas on the application instance
    setattr(app, "default_observer_schemas", defaults)
    return defaults

