    for filename in config_filenames:
        try:
            with open(filename, 'r') as f:
                raw = f.read()
            try:
                cfg = json.loads(raw)
            except Exception as e:
                record = logging.LogRecord(
                    name='load_configurations',
                    level=logging.ERROR,
                    pathname=filename,
                    lineno=0,
                    msg=f'Error parsing {filename}: {e}',
                    args=(),
                    exc_info=None
                )
                error_records.append(record)
                continue
            if overrides and isinstance(cfg, dict):
                cfg.update(overrides)
            elif overrides:
                record = logging.LogRecord(
                    name='load_configurations',
                    level=logging.ERROR,
                    pathname=filename,
                    lineno=0,
                    msg=f'Cannot apply overrides to non-dict config in {filename}',
                    args=(),
                    exc_info=None
                )
                error_records.append(record)
                continue
            if resolve_env:
                import re
                pattern = re.compile(r'\$\{([^}]+)\}')
                def repl(match):
                    var = match.group(1)
                    return __import__('os').environ.get(var, match.group(0))
                def resolve(obj):
                    if isinstance(obj, str):
                        return pattern.sub(repl, obj)
                    if isinstance(obj, dict):
                        return {k: resolve(v) for k, v in obj.items()}
                    if isinstance(obj, list):
                        return [resolve(v) for v in obj]
                    return obj
                cfg = resolve(cfg)
            results[filename] = cfg
        except Exception as e:
            record = logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f'Error loading {filename}: {e}',
                args=(),
                exc_info=None
            )
            error_records.append(record)
    return results, error_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import json, re, os, logging
    config_map = {}
    log_records = []
    env_pattern = re.compile(r'\$\{([^}]+)\}')

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                content = f.read()
            if resolve_env:
                content = env_pattern.sub(lambda m: os.getenv(m.group(1), ''), content)
            config = json.loads(content)
            if overrides:
                if isinstance(overrides, dict):
                    # override top‑level keys
                    config.update(overrides)
                else:
                    raise TypeError("overrides must be a dict if provided")
            config_map[filename] = config
        except Exception as e:
            rec = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=str(e),
                args=(),
                exc_info=None
            )
            log_records.append(rec)

    return config_map, log_records

