    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: parsed XML root element (representing XRD)
    """
    # Build the host-meta URL
    base = host.strip()
    if not base.startswith(("http://", "https://")):
        base = f"https://{base}"
    if base.endswith("/"):
        base = base.rstrip("/")
    url = f"{base}/.well-known/host-meta"

    # Set up a request that accepts XRD
    try:
        import urllib.request
        import urllib.error
        import ssl
        req = urllib.request.Request(url, headers={"Accept": "application/xrd+xml"}, method="GET")
        context = ssl._create_unverified_context()
        with urllib.request.urlopen(req, context=context, timeout=10) as resp:
            if resp.status != 200:
                raise RuntimeError(f"[{host}] Failed to retrieve host-meta: HTTP {resp.status}")
            content = resp.read()
    except urllib.error.HTTPError as e:
        raise RuntimeError(f"[{host}] HTTP error {e.code} retrieving host-meta") from e
    except urllib.error.URLError as e:
        raise RuntimeError(f"[{host}] Connection error retrieving host-meta: {e}") from e
    except Exception as e:
        raise RuntimeError(f"[{host}] Unexpected error retrieving host-meta: {e}") from e

    # Parse the XML into an ElementTree element
    try:
