def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    cmd = ['ansible-playbook', playbook_path]
    if verbose:
        if isinstance(verbose, int) and verbose > 0:
            cmd.append('-' + 'v' * verbose)
        else:
            cmd.append('-v')
    if ansible_args:
        for key, value in ansible_args.items():
            opt = f'--{key}'
            if isinstance(value, bool):
                if value:
                    cmd.append(opt)
            else:
                cmd.append(opt)
                cmd.append(str(value))
    if extra_vars:
        kv = []
        for k, v in extra_vars.items():
            kv.append(f'{k}={v}')
        cmd.extend(['--extra-vars', ' '.join(kv)])
    env = dict(os.environ)
    env.update(ir_workspace.env if hasattr(ir_workspace, "env") else {})
    result = subprocess.run(cmd, capture_output=True, text=True, env=env)
    if ir_plugin and hasattr(ir_plugin, "logger"):
        ir_plugin.logger.info(result.stdout)
        if result.returncode != 0:
            ir_plugin.logger.error(result.stderr)
    if result.returncode != 0:
        raise RuntimeError(f"ansible-playbook failed (exit {result.returncode}): {result.stderr}")
    return result.stdout

