def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("path and root must be strings")
    if root == "":
        return path
    # Normalize separators to forward slash for comparison
    norm_path = path.replace("\\", "/")
    norm_root = root.replace("\\", "/")
    if not norm_root.endswith("/"):
        norm_root = norm_root + "/"
    if norm_path.startswith(norm_root):
        rest = norm_path[len(norm_root):]
    else:
        # Try exact match without trailing slash
        if norm_path == norm_root.rstrip("/"):
            rest = ""
        else:
            raise ValueError(f"Root '{root}' not found in path '{path}'")
    # Return with original separator of path
    sep = "/" if "/" in path else "\\"
    return rest.replace("/", sep).lstrip(sep) if rest else ""
